INSERT INTO sys_login_log_archive (
  id, tenant_id, username, login_type, login_status, message, ip, location, user_agent, browser, os, login_at, prev_hash, row_hash, archived_at
)
SELECT id, tenant_id, username, login_type, login_status, message, ip, location, user_agent, browser, os, login_at, prev_hash, row_hash, NOW(3)
FROM sys_login_log
WHERE login_at < #{before}

